var n=`0678-tiguadege-na`;var i=`world-0678`;var a=`ML`;var s=`western-africa`;var o=4;var r=79;var g={en:`Tiguadege Na`,ua:`Тігадеге на`};var l={en:`Tiguadege Na is a Mali classic prepared with lamb, yellow onion, peanut butter, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Тігадеге на, страва кухні країни Малі зі складниками: ягнятина, жовта цибуля, арахісова паста, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`lamb`,640,`g`],[`red-palm-oil`,40,`ml`],[`yellow-onion`,170,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`peanut-butter`,190,`g`],[`water`,850,`ml`],[`tomato`,300,`g`],[`sweet-potato`,270,`g`],[`carrot`,200,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,15,`g`],[`table-salt`,null,`to_taste`]]}];var d={slug:n,id:i,country:`ML`,region:s,servings:4,minutes:79,title:g,text:l,steps:u};export{a as country,d as default,i as id,r as minutes,s as region,o as servings,n as slug,u as steps,l as text,g as title};